import{_ as a,o,c as n,a2 as t}from"./chunks/framework.2af478d7.js";const p=JSON.parse('{"title":"0001. Content cache keyed by a global generation, invalidated by webhook","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0001-content-cache-with-generation-key.md","filePath":"adr/0001-content-cache-with-generation-key.md"}'),s={name:"adr/0001-content-cache-with-generation-key.md"};function r(i,e,d,c,l,h){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="_0001-content-cache-keyed-by-a-global-generation-invalidated-by-webhook" tabindex="-1">0001. Content cache keyed by a global generation, invalidated by webhook <a class="header-anchor" href="#_0001-content-cache-keyed-by-a-global-generation-invalidated-by-webhook" aria-label="Permalink to &quot;0001. Content cache keyed by a global generation, invalidated by webhook&quot;">​</a></h1><p>Status: accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Every page depends on Drupal JSON:API round-trips. Drupal exposes no ETag, <code>changed</code> field or push mechanism, and the production cache store is database-backed (no tags, no cheap key scan). No CDN or reverse proxy fronts the site.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ul><li>A thin caching layer (<code>CachedDrupal</code>) sits between the fetchers and <code>DrupalClient</code> and stores decoded JSON:API document arrays, never models. Alias resolution is cached the same way, as <code>[endpoint, resourceName, bundle]</code>.</li><li>Freshness is stale-while-revalidate: fresh 5 min, stale 24 h (also the stale-if-error window). Both are env-tunable.</li><li>Every key includes one global content-generation counter. A signed webhook (<code>POST /hooks/drupal</code>, HMAC-SHA256 of <code>&quot;{timestamp}.{raw body}&quot;</code> with a timestamp tolerance, each signature accepted once, 404 while no secret is set) and <code>php artisan drupal:flush</code> replace it with a new UUID.</li><li>Every <code>CachedDrupal</code> instance shares the store and the generation key, including the one wrapping the separate reviews site, so one flush invalidates all of them.</li><li>Unknown aliases are cached as not-found for 60 s (<code>DRUPAL_CACHE_NEGATIVE</code>); unavailable and bad-response outcomes are never cached. An alias that resolves to the wrong kind of resource is not-found but is not cached negatively.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Invalidation is coarse: any change refetches everything lazily. Acceptable at this site&#39;s size.</li><li>Old generations expire by TTL; no purge query is needed.</li><li>Until Drupal ships the webhook sender, only the fresh window and the flush command apply.</li><li>Moving to a tag-capable store (Redis) would allow finer invalidation and needs separate approval.</li><li>Search results are an exception to stale-while-revalidate: they use a short fresh-only window (60 s by default, no stale-if-error; <code>DRUPAL_CACHE_SEARCH=0</code> disables it) and the suggestions endpoint is not cached, because search keys are high-cardinality and users expect near-live results. Search keys still embed the generation, so a flush clears them. See ADR 0002 for how search queries are built.</li><li><code>DRUPAL_CACHE_ENABLED=false</code> bypasses every layer above.</li></ul><h2 id="addendum-one-generation-per-source" tabindex="-1">Addendum: one generation per Source <a class="header-anchor" href="#addendum-one-generation-per-source" aria-label="Permalink to &quot;Addendum: one generation per Source&quot;">​</a></h2><p>When the system serves several Drupal backends (Sources), each Source has its own generation key, replacing the single shared key stated above. A webhook for one Source bumps only that Source&#39;s generation, plus the generations of the Sources listed in its <code>flush.also.sources</code>. <code>drupal:flush</code> with no argument flushes every Source; <code>drupal:flush &lt;source&gt;</code> flushes one.</p><h2 id="update-2026-10-25" tabindex="-1">Update (2026-10-25) <a class="header-anchor" href="#update-2026-10-25" aria-label="Permalink to &quot;Update (2026-10-25)&quot;">​</a></h2><p>The decision stands. The code moved into the package and some names changed:</p><ul><li><code>DrupalManager</code> hands out one <code>CachedDrupal</code> per Source, and <code>DrupalManager::flush()</code> follows <code>flush.also.sources</code>.</li><li>Keys are <code>drupal:{source}:{generation}:{sha1}</code>. The generation lives under <code>drupal:generation:{source}</code>. The &quot;global generation&quot; in the Decision section is superseded by the addendum above.</li><li>The fresh, stale, negative and search windows are shipped as defaults in the package&#39;s <code>config/drupal.php</code> and read from <code>drupal.cache.*</code> and <code>search.cache</code>.</li><li>The webhook sender is specified by <code>php artisan drupal:contract</code>, which prints the payload, headers and a reference snippet. See the <a href="./../webhook-and-cache-flushing">Webhook and cache flushing</a> and <a href="./../caching-model">Caching model</a> pages.</li></ul>',13)])])}const g=a(s,[["render",r]]);export{p as __pageData,g as default};
